body { background-color: var(--mag-bg); color: var(--mag-text); font-family: var(--font-text); -webkit-font-smoothing: antialiased; }

h1, h2, h3, h4, h5, h6, .playfair { font-family: var(--font-title); color: var(--mag-title); }

a { color: var(--mag-primary); text-decoration: none; transition: color 0.3s; }

a:hover { color: #1d4ed8; }

.mag-header-content { padding-top: 1rem; padding-bottom: 1rem; text-align: center; }

.mag-logo-link { display: inline-block; }

.mag-logo-img { max-height: 90px; width: auto; }

.navbar-container { border-top: 1px solid var(--mag-border); border-bottom: 4px solid var(--mag-dark); background-color: var(--mag-surface); }

[data-bs-theme="dark"] .navbar-container { border-bottom-color: var(--mag-primary); }

.navbar .nav-link { font-family: var(--font-text); font-weight: 500; text-transform: uppercase; letter-spacing: 1px; font-size: 0.85rem; color: var(--mag-title) !important; padding: 15px 20px !important; }

.navbar .nav-link:hover { color: var(--mag-primary) !important; }

.news-card { background: transparent; border: none; transition: transform 0.3s; height: 100%; }

.news-card:hover .news-title a { color: var(--mag-primary); }

.news-card-img { overflow: hidden; border-radius: 4px; position: relative; margin-bottom: 1rem; }

.news-card-img img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.5s; }

.news-card:hover .news-card-img img { transform: scale(1.03); }

.news-title { font-weight: 700; font-size: 1.4rem; line-height: 1.3; }

.news-title a { color: var(--mag-title); }

.post-header-single { text-align: center; margin-bottom: 3rem; padding-bottom: 2rem; border-bottom: 1px solid var(--mag-border); }

.post-title-single { font-weight: 900; font-size: clamp(2.5rem, 5vw, 4rem); line-height: 1.1; margin: 15px 0; letter-spacing: -1px; }

.post-body-content { font-size: 1.15rem; line-height: 1.8; color: var(--mag-text); }

.post-body-content img, .post-body-content iframe { max-width: 100% !important; height: auto !important; margin: 2rem 0; border-radius: 8px; box-shadow: 0 4px 15px rgba(0,0,0,0.05); }

.post-body-content > p:first-of-type::first-letter, 
    .post-body-content > div:first-of-type::first-letter {
      font-family: var(--font-title);
      font-size: 4.5rem;
      font-weight: 900;
      color: var(--mag-primary);
      float: left;
      line-height: 0.8;
      margin-right: 12px;
      margin-top: 5px;
    }

.error-404-wrapper { min-height: 50vh; display: flex; flex-direction: column; justify-content: center; align-items: center; text-align: center; padding: 4rem 1rem; }

.error-code { font-family: var(--font-title); font-size: clamp(6rem, 15vw, 12rem); color: var(--mag-title); font-weight: 900; line-height: 1; letter-spacing: -5px; }

.error-subtitle { font-family: var(--font-title); font-style: italic; color: var(--mag-primary); }

.list-label-widget-content ul, .cloud-label-widget-content { list-style: none !important; padding: 0 !important; margin: 0 !important; display: flex; flex-wrap: wrap; gap: 8px; }

.list-label-widget-content ul li, .cloud-label-widget-content .label-size { display: inline-flex; align-items: center; margin: 0; }

.list-label-widget-content ul li a, .cloud-label-widget-content .label-size a, .post-bottom-tags a {
      display: inline-flex; align-items: center; background: transparent; color: var(--mag-text);
      font-size: 0.8rem !important; font-weight: 600; text-transform: uppercase; letter-spacing: 1px;
      padding: 8px 18px; border-radius: 30px; border: 1px solid var(--mag-border);
      transition: all 0.3s ease; text-decoration: none !important;
    }

.list-label-widget-content ul li a:hover, .cloud-label-widget-content .label-size a:hover, .post-bottom-tags a:hover {
      background: var(--mag-primary); color: #ffffff !important; border-color: var(--mag-primary); transform: translateY(-3px); box-shadow: 0 6px 15px rgba(37, 99, 235, 0.2);
    }

.list-label-widget-content ul li span[dir='ltr'], .cloud-label-widget-content .label-count {
      background: var(--mag-dark); color: #ffffff; font-size: 0.7rem; padding: 2px 8px; border-radius: 12px; margin-left: -12px; margin-top: -15px; font-weight: 700; z-index: 2; border: 2px solid var(--mag-surface);
    }

[data-bs-theme="dark"] .list-label-widget-content ul li a, [data-bs-theme="dark"] .cloud-label-widget-content .label-size a { border-color: #334155; }

[data-bs-theme="dark"] .list-label-widget-content ul li span[dir='ltr'], [data-bs-theme="dark"] .cloud-label-widget-content .label-count { border-color: var(--mag-surface); }

.mag-newsletter { background: var(--mag-dark); color: #fff; padding: 2rem; border-radius: 8px; text-align: center; }

.mag-newsletter h4 { font-family: var(--font-title); color: #fff; font-size: 1.8rem; margin-bottom: 1rem; }

[data-bs-theme="dark"] .mag-newsletter { background: var(--mag-surface); border: 1px solid var(--mag-border); }

.mag-footer { background-color: var(--sl-footer-bg); color: var(--sl-text-main); padding-top: 5rem; margin-top: 5rem; }

.mag-footer .playfair { color: #ffffff; }

.mag-footer .widget-title { color: #ffffff; border-bottom-color: #374151; }

.mag-footer a { color: var(--sl-text-main); text-decoration: none; transition: color 0.3s ease; }

.mag-footer a:hover { color: var(--mag-primary); }

.mag-footer .btn-social { border-color: #374151; color: #d1d5db; transition: all 0.3s ease; }

.mag-footer .btn-social:hover { background-color: var(--mag-primary); border-color: var(--mag-primary); color: #ffffff; transform: translateY(-3px); }

.mag-footer-bottom { border-top: 1px solid #1f2937; padding: 1.5rem 0; margin-top: 3rem; }

#sl-back-top {
      position: fixed;
      bottom: 30px;
      right: 30px;
      width: 50px;
      height: 50px;
      background-color: var(--mag-primary);
      color: #ffffff;
      border: none;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.8rem;
      box-shadow: 0 4px 15px rgba(37, 99, 235, 0.4);
      cursor: pointer;
      opacity: 0;
      visibility: hidden;
      transform: translateY(20px);
      transition: all 0.3s ease;
      z-index: 999;
    }

#sl-back-top.show {
      opacity: 1;
      visibility: visible;
      transform: translateY(0);
    }

#sl-back-top:hover {
      background-color: #1d4ed8;
      transform: translateY(-5px);
      box-shadow: 0 6px 20px rgba(37, 99, 235, 0.6);
    }

